-- Daily challenges for 2026-11-07: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-11-07. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('buying-less-enjoying-more', 'Buying Less, Enjoying More', 'For anyone who wants fewer impulse buys and more joy in what they already have. Each day is one small way to pause before buying, use and share what you own, and spend on what truly matters to you.', 'Values', 365, array['Money', 'Habits', 'Values']::text[], 1, '2026-11-07T17:00:00+00:00'::timestamptz),
  ('being-a-thoughtful-guest', 'Being a Thoughtful Guest', 'For anyone who wants to feel more at ease visiting other people''s homes, from a family dinner to a weekend stay. Each day is one small way to arrive kindly, help a little, respect the household and leave a warm thank you behind.', 'Connection', 365, array['Relationships', 'Communication', 'Social Anxiety']::text[], 1, '2026-11-07T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('buying-less-enjoying-more', 'being-a-thoughtful-guest');

